cd /srv/web-backend; python3 -c "
import json,collections
d=json.load(open('result.json'))
print(d['viztracer_metadata'])
ev=[e for e in d['traceEvents'] if e['ph']=='X']
def kids(p):
  return [e for e in ev if e['tid']==p['tid'] and e['ts']>=p['ts'] and e['ts']+e['dur']<=p['ts']+p['dur'] and e is not p]
for nm in ['list_orders','discount_for','create (','database']:
  for p in [e for e in ev if e['name'].startswith(nm)]:
    k=kids(p); print(nm,p['ts'],p['dur'],collections.Counter(e['name'] for e in k).most_common(15))
for e in ev:
  if 'unlink' in e['name'] or 'args' in e and e['name'].startswith('discount'): print(e)
"

